      "path": "package.json",
      "content": "{\n  \"name\": \"@99galaxy/dsh-plugin-market\",\n  \"version\": \"1.1.1\",\n  \"type\": \"module\",\n  \"description\": \"DSH 插件市场：在设置面板中浏览 awesome-dsh-plugin 目录并一键安装。Browse the awesome-dsh-plugin catalog inside Settings and install plugins.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/99galaxy/dsh-plugin-market.git\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"main\": \"index.js\",\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./client/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"market-core.mjs\",\n    \"client\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  }\n}\n"
